"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["22148"],{888387(n){n.exports=JSON.parse('{"id":6649,"title":"\u6839\u636Etext\u6587\u672C\u521B\u4F5C\u8BBE\u8BA1\u77ED\u89C6\u9891\u5C01\u9762\u56FE\u7247Prompt","description":"\u4F60\u7684\u4EFB\u52A1\u662F\u6839\u636E\u63D0\u4F9B\u7684\u6587\u6848\uFF0C\u6309\u7167\u7ED9\u5B9A\u7684\u77ED\u89C6\u9891\u5C01\u9762\u56FE\u7247\u8BBE\u8BA1\u8981\u70B9\uFF0C\u7F16\u5199\u4E00\u4E2A\u77ED\u89C6\u9891\u5C01\u9762\u56FE\u7247\u521B\u4F5C\u7684\u63D0\u793A\u8BCD\uFF0C\u4EE5\u5B8C\u6210\u4F18\u8D28\u7684\u5C01\u9762\u56FE\u7247\u8BBE\u8BA1\u3002\\n\u4EE5\u4E0B\u662F\u4F60\u9700\u8981\u53C2\u8003\u7684\u6587\u6848\uFF1A\\n<\u6587\u6848>\\n{{text}}\\n</\u6587\u6848>\\n\u5728\u7F16\u5199\u63D0\u793A\u8BCD\u65F6\uFF0C\u8BF7\u4E25\u683C\u9075\u5FAA\u4EE5\u4E0B\u77ED\u89C6\u9891\u5C01\u9762\u56FE\u7247\u8BBE\u8BA1\u8981\u70B9\uFF1A\\n#### 1. **\u89C6\u89C9\u5438\u5F15\u529B**\\n- **\u8272\u5F69\u642D\u914D**\uFF1A\u4F7F\u7528\u9AD8\u5BF9\u6BD4\u5EA6\u7684\u989C\u8272\u7EC4\u5408\uFF0C\u5982\u767D\u8272\u642D\u914D\u4EAE\u8272\uFF0C\u80FD\u5FEB\u901F\u5438\u5F15\u7528\u6237\u6CE8\u610F\u529B\u3002\\n- **\u5B57\u4F53\u8BBE\u8BA1**\uFF1A\u9009\u62E9\u7B80\u6D01\u6613\u8BFB\u7684\u5B57\u4F53\uFF0C\u907F\u514D\u8FC7\u4E8E\u590D\u6742\u6216\u5C0F\u5B57\u4F53\uFF0C\u786E\u4FDD\u6587\u5B57\u6E05\u6670\u3002\\n- **\u6392\u7248\u7B80\u6D01**\uFF1A\u907F\u514D\u8FC7\u591A\u6587\u5B57\u6216\u5143\u7D20\uFF0C\u4FDD\u6301\u5E03\u5C40\u5E72\u51C0\uFF0C\u7A81\u51FA\u6838\u5FC3\u4FE1\u606F\u3002\\n\\n#### 2. **\u6587\u6848\u4E0E\u5C01\u9762\u7684\u5951\u5408**\\n- **\u6587\u6848\u7684\u91CD\u8981\u6027**\uFF1A\u6587\u6848\u662F\u89C6\u9891\u7684\u6838\u5FC3\uFF0C\u5E94\u4E0E\u5C01\u9762\u8BBE\u8BA1\u76F8\u8F85\u76F8\u6210\uFF0C\u4F20\u8FBE\u89C6\u9891\u4E3B\u9898\u3002\\n- **\u6587\u6848\u4F4D\u7F6E**\uFF1A\u901A\u5E38\u4F4D\u4E8E\u5C01\u9762\u9876\u90E8\u6216\u5E95\u90E8\uFF0C\u786E\u4FDD\u6587\u6848\u5185\u5BB9\u4E0E\u89C6\u9891\u5185\u5BB9\u9AD8\u5EA6\u76F8\u5173\u3002\\n- **\u6587\u6848\u957F\u5EA6**\uFF1A\u7B80\u77ED\u6709\u529B\uFF0C\u907F\u514D\u5197\u957F\uFF0C\u786E\u4FDD\u7528\u6237\u5FEB\u901F\u7406\u89E3\u89C6\u9891\u5185\u5BB9\u3002\\n\\n#### 3. **\u573A\u666F\u4E0E\u6C1B\u56F4**\\n- **\u81EA\u7136\u573A\u666F**\uFF1A\u9002\u5408\u8F7B\u677E\u3001\u81EA\u7136\u7684\u89C6\u9891\uFF0C\u5982\u98CE\u666F\u3001\u65E5\u5E38\u6D3B\u52A8\u3002\\n- **\u79D1\u6280\u573A\u666F**\uFF1A\u9002\u5408\u79D1\u6280\u3001\u6559\u7A0B\u7C7B\u89C6\u9891\uFF0C\u4F7F\u7528\u79D1\u6280\u611F\u5143\u7D20\u3002\\n- **\u60C5\u611F\u573A\u666F**\uFF1A\u5982\u611F\u4EBA\u6545\u4E8B\u3001\u60C5\u611F\u7C7B\u89C6\u9891\uFF0C\u91C7\u7528\u6E29\u6696\u6216\u60C5\u611F\u4E30\u5BCC\u7684\u5143\u7D20\u3002\\n\\n#### 4. **\u4E2A\u6027\u5316\u8BBE\u8BA1**\\n- **\u7528\u6237\u753B\u50CF**\uFF1A\u6839\u636E\u76EE\u6807\u7528\u6237\u7684\u5174\u8DA3\u548C\u559C\u597D\u8BBE\u8BA1\uFF0C\u589E\u52A0\u89C6\u9891\u7684\u5438\u5F15\u529B\u3002\\n- **\u4E2A\u6027\u5316\u5143\u7D20**\uFF1A\u5982\u7528\u6237\u5934\u50CF\u3001\u6635\u79F0\u7B49\uFF0C\u589E\u52A0\u4EB2\u5207\u611F\u3002\\n\\n#### 5. **\u4E3B\u9898\u7EDF\u4E00**\\n- **\u98CE\u683C\u4E00\u81F4\u6027**\uFF1A\u4FDD\u6301\u89C6\u9891\u548C\u5C01\u9762\u7684\u98CE\u683C\u4E00\u81F4\uFF0C\u5982\u7EDF\u4E00\u4F7F\u7528\u7B80\u7EA6\u6216\u5361\u901A\u98CE\u683C\u3002\\n- **\u89C6\u89C9\u534F\u8C03**\uFF1A\u989C\u8272\u3001\u5B57\u4F53\u3001\u6392\u7248\u7B49\u5143\u7D20\u4FDD\u6301\u534F\u8C03\uFF0C\u907F\u514D\u7A81\u5140\u3002\\n\\n#### 6. **\u521B\u65B0\u4E0E\u4E92\u52A8**\\n- **\u521B\u610F\u5143\u7D20**\uFF1A\u5982\u52A8\u6001\u80CC\u666F\u3001\u6E10\u53D8\u8272\u3001\u6D6E\u96D5\u7B49\uFF0C\u63D0\u5347\u89C6\u89C9\u6548\u679C\u3002\\n- **\u4E92\u52A8\u8BBE\u8BA1**\uFF1A\u5982\u7528\u6237\u8BC4\u8BBA\u533A\u7684\u4E92\u52A8\u5143\u7D20\uFF0C\u589E\u52A0\u7528\u6237\u53C2\u4E0E\u611F\u3002\\n\\n#### 7. **\u53CA\u65F6\u6027\u4E0ESEO**\\n- **\u5185\u5BB9\u66F4\u65B0**\uFF1A\u53CA\u65F6\u66F4\u65B0\u5C01\u9762\u56FE\u7247\uFF0C\u4FDD\u6301\u89C6\u9891\u7684\u65B0\u9C9C\u611F\u3002\\n- **\u5173\u952E\u8BCD\u4F18\u5316**\uFF1A\u8BBE\u8BA1\u5C01\u9762\u65F6\u878D\u5165\u76F8\u5173\u5173\u952E\u8BCD\uFF0C\u63D0\u5347\u641C\u7D22\u5F15\u64CE\u6392\u540D\u3002\\n\\n\u8BF7\u5728<\u63D0\u793A\u8BCD>\u6807\u7B7E\u5185\u5199\u4E0B\u4F60\u7684\u77ED\u89C6\u9891\u5C01\u9762\u56FE\u7247\u521B\u4F5C\u63D0\u793A\u8BCD\u3002\u786E\u4FDD\u63D0\u793A\u8BCD\u5168\u9762\u8003\u8651\u4E86\u4E0A\u8FF0\u6240\u6709\u8981\u70B9\uFF0C\u4EE5\u6307\u5BFC\u8BBE\u8BA1\u51FA\u4F18\u8D28\u7684\u5C01\u9762\u56FE\u7247\u3002","remark":"\u5C01\u9762\u56FE\u7247\u8BBE\u8BA1","notes":"\u6587\u672C  \u5C01\u9762\u56FE\u7247","owner":"\u5DF4\u671B\u522B\u96C6","upvotes":7,"downvotes":1,"upvoteDifference":6,"updatedAt":"2026-05-31T05:38:47.511Z"}')}}]);